package com.cpgame.batchd.treasurehunt.api;
import com.cpgame.batchd.treasurehunt.core.GameRuleCore;import com.cpgame.batchd.treasurehunt.core.MinimalRoundFactCodec;import com.cpgame.batchd.treasurehunt.core.ResultUtil;import java.security.SecureRandom;import java.util.ArrayList;import java.util.List;
final class CacheRepository{enum Pool{ORDINARY_LOSS,ORDINARY_WIN,TREASURE_HUNT,ALL_REELS_MULTIPLIER}private final ServerConfig config;private final SecureRandom random=new SecureRandom();CacheRepository(ServerConfig c){config=c;}GameRuleCore.CompleteRound take(Pool pool){boolean special=pool==Pool.TREASURE_HUNT||pool==Pool.ALL_REELS_MULTIPLIER;String index=String.format(special?"MaryKeyList_%09d":"PerKeyList_%09d",config.gameId());try(var redis=config.openRedis()){List<Integer> multipliers=new ArrayList<>();for(String v:redis.zrange(index,0,-1)){int m=Integer.parseInt(v);if(special||(pool==Pool.ORDINARY_LOSS?m==0:m>0))multipliers.add(m);}int attempts=Math.max(40,multipliers.size()*4);while(attempts-->0&&!multipliers.isEmpty()){int m=multipliers.get(random.nextInt(multipliers.size()));String key=special?String.format("MaryLog:%09d:%06d",config.gameId(),m):String.format("BetLog:0%08d:%06d",config.gameId(),m);long n=redis.llen(key);if(n<=0){multipliers.remove(Integer.valueOf(m));continue;}String fact=redis.lindex(key,random.nextInt((int)Math.min(n,Integer.MAX_VALUE)));if(fact==null){multipliers.remove(Integer.valueOf(m));continue;}var round=MinimalRoundFactCodec.decode(fact);var eval=ResultUtil.calculate(fact);if(eval.totalUnits()!=m)throw new IllegalStateException("Redis member multiplier mismatch");boolean match=switch(pool){case ORDINARY_LOSS->round.mode()==GameRuleCore.Mode.ORDINARY&&eval.outcome()==GameRuleCore.Outcome.LOSS;case ORDINARY_WIN->round.mode()==GameRuleCore.Mode.ORDINARY&&eval.outcome()==GameRuleCore.Outcome.WIN;case TREASURE_HUNT->round.mode()==GameRuleCore.Mode.TREASURE_HUNT;case ALL_REELS_MULTIPLIER->round.mode()==GameRuleCore.Mode.ALL_REELS_MULTIPLIER;};if(match)return round;}}throw new IllegalStateException("requested Redis cache pool is empty: "+pool);}}
